client_script:
frappe.web_form.after_load = () => {
	const urlParams = new URLSearchParams(window.location.search);
	const contactType = urlParams.get('type');
	
	if (contactType && contactType == "caregiver"){
	    const introText = 'If you are a Paramedic - Nurse, Geriatric Care Giver or GDA and would like to work in Home Care, ' +
                		    'pls fill the form.\n We will call you. Once onboard, you can get regular work and also can get' +
                		    ' a job offer from the company.\nPlease fill the form below to start working:';
		$intro = $('.web-form-introduction');
		
		// Change the text for Caregivers who want to contact us
		$intro.empty().append(introText);
	}
};
